body.template:
---
apiVersion: v1
kind: PersistentVolume
metadata:
  name: postgres-pv-{{.ident}}
spec:
  storageClassName: {{.storageClass}}
  capacity:
    storage: {{.capacity}}
  accessModes:
  - {{.accessModes}}
  hostPath:
    path: "/mnt/data"
---
apiVersion: v1
kind: PersistentVolumeClaim
metadata:
  name: postgres-pvc-{{.ident}}
spec:
  storageClassName: {{.storageClass}}
  accessModes:
  - {{.accessModes}}
  resources:
    requests:
      storage: {{$affif.volumeSize}}

